'use strict';
async function refreshMetrics(){const status=document.getElementById('metrics-status'),button=document.getElementById('refresh-metrics');button.disabled=true;status.textContent='Cargando estadísticas…';try{const response=await fetch('/api/site-metrics',{cache:'no-store'});const data=await response.json();if(!response.ok){document.getElementById('metrics-summary').replaceChildren();throw Error(data.error||'No disponible');}const totals={view:0,amazon:0,whatsapp:0};for(const row of data.rows)totals[row.event]+=row.count;const summary=document.getElementById('metrics-summary');summary.replaceChildren();for(const [title,value]of [['Vistas registradas',totals.view],['Clics hacia Amazon',totals.amazon],['Tasa de clics a Amazon',totals.view?(100*totals.amazon/totals.view).toFixed(1)+' %':'Sin datos']]){const p=document.createElement('p');p.textContent=title+': '+value;summary.append(p);}status.textContent=data.rows.length?'Datos actualizados.':'Todavía no hay eventos con consentimiento.';}catch(e){status.textContent=e.message;}finally{button.disabled=false;}}
document.getElementById('refresh-metrics').addEventListener('click',refreshMetrics);refreshMetrics();

const ownerElement=id=>document.getElementById(id);
async function teamApi(path,body){const response=await fetch('/api/community/'+path,{cache:'no-store',credentials:'same-origin',...(body?{method:'POST',headers:{'Content-Type':'application/json','X-Community-Action':'write'},body:JSON.stringify(body)}:{})});const data=await response.json();if(!response.ok){if(response.status===401||response.status===403){ownerElement('team-members').replaceChildren();ownerElement('team-candidate').replaceChildren();ownerElement('team-section').hidden=true;}throw Error(data.error||'No se ha podido completar la acción.');}return data;}
function teamText(tag,value){const element=document.createElement(tag);element.textContent=value;return element;}
let teamBusy=false;
async function changeRole(member,grant){if(teamBusy||!confirm((grant?'Dar permisos de dueño a ':'Retirar permisos de dueño a ')+member.alias+' ('+member.email+')'+(grant?' permitirá moderar conversaciones y consultar estadísticas. ¿Continuar?':' impedirá su acceso privado. ¿Continuar?')))return;teamBusy=true;try{await teamApi('team/'+(grant?'grant':'revoke'),{userId:member.id,email:member.email,confirmed:true});ownerElement('team-candidate').replaceChildren();await loadTeam();ownerElement('team-status').textContent=grant?'Nuevo dueño añadido. Ya puede entrar con Google.':'Permisos retirados.';}catch(e){ownerElement('team-status').textContent=e.message;}finally{teamBusy=false;}}
function memberCard(member,grant=false){const card=teamText('div','');card.className='team-person';card.append(teamText('strong',member.alias),teamText('p',member.email));if(member.principal)card.append(teamText('p','Dueño principal · Cuenta protegida'));else{const button=teamText('button',grant?'Confirmar nuevo dueño':'Retirar permisos');button.type='button';button.className='secondary';button.addEventListener('click',()=>changeRole(member,grant));card.append(button);}return card;}
async function loadTeam(){const data=await teamApi('team');ownerElement('team-members').replaceChildren(...data.members.map(member=>memberCard(member)));}
ownerElement('team-form').addEventListener('submit',async event=>{event.preventDefault();if(teamBusy)return;teamBusy=true;ownerElement('team-candidate').replaceChildren();try{const data=await teamApi('team/lookup',{email:ownerElement('team-email').value.trim()});ownerElement('team-candidate').append(memberCard(data.member,true));ownerElement('team-status').textContent='Comprueba la cuenta antes de conceder acceso.';}catch(e){ownerElement('team-status').textContent=e.message;}finally{teamBusy=false;}});
teamApi('me').then(async data=>{if(data.canManageOwners){ownerElement('team-section').hidden=false;await loadTeam();}}).catch(e=>{ownerElement('metrics-status').textContent=e.message;});

async function loadModerationHistory(){try{const data=await teamApi('moderation-history');ownerElement('moderation-history').replaceChildren(...data.events.map(event=>{const item=teamText('div','');item.className='team-person';item.append(teamText('strong',event.action==='published'?'Aprobada':'Retirada'),teamText('p',event.actor+' · '+new Date(event.createdAt).toLocaleString('es-ES')),teamText('p',event.reason||'Aprobada conforme a las normas.'));return item;}));ownerElement('moderation-status').textContent=data.events.length?'Últimas '+data.events.length+' decisiones.':'Todavía no hay decisiones de moderación.';}catch(e){ownerElement('moderation-history').replaceChildren();ownerElement('moderation-status').textContent=e.message;}}
ownerElement('refresh-moderation').addEventListener('click',loadModerationHistory);
loadModerationHistory();

async function loadReports(){const status=ownerElement('reports-status');try{const data=await teamApi('reports');ownerElement('community-reports').replaceChildren(...data.reports.map(report=>{const card=teamText('article','');card.className='team-person';card.append(teamText('h4',report.title||'Aviso sobre una respuesta'),teamText('p','Aviso de '+report.reporter+' · '+new Date(report.createdAt).toLocaleString('es-ES')),teamText('p',report.reason),teamText('blockquote',report.body));const link=teamText('a','Abrir conversación y moderar');link.href='/comunidad?conversacion='+encodeURIComponent(report.threadId);card.append(link);const form=document.createElement('form'),label=teamText('label','Decisión sobre el aviso'),input=document.createElement('input');input.id='resolution-'+report.id;label.htmlFor=input.id;input.required=true;input.minLength=3;input.maxLength=500;const submit=teamText('button','Marcar como revisado');submit.className='secondary';submit.type='submit';form.append(label,input,submit);form.addEventListener('submit',async e=>{e.preventDefault();submit.disabled=true;try{await teamApi('reports/resolve',{id:report.id,resolution:input.value});await loadReports();}catch(error){status.textContent=error.message;}finally{submit.disabled=false;}});card.append(form);return card;}));status.textContent=data.reports.length?data.reports.length+' avisos pendientes en esta tanda.':'No hay avisos pendientes.';}catch(e){ownerElement('community-reports').replaceChildren();status.textContent=e.message;}}
ownerElement('refresh-reports').addEventListener('click',loadReports);loadReports();
